from pathlib import Path

p = Path('src/session/supabase.ts')
s = p.read_text()
old = "const SUPABASE_URL = import.meta.env.VITE_SUPABASE_URL ?? 'https://meigiiqcrvwxcgapzxxi.supabase.co'\nconst SUPABASE_PUBLISHABLE_KEY = import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY ?? 'sb_publishable_8BlWpHJsYzB2V8GQh9kqdQ_QUjg7rN-'\n\nexport const supabase = createClient(SUPABASE_URL, SUPABASE_PUBLISHABLE_KEY, {"
new = """const SUPABASE_CONFIG_STORAGE_KEY = 'eduvent.supabase-config'\nconst DEFAULT_SUPABASE_URL = 'https://meigiiqcrvwxcgapzxxi.supabase.co'\nconst DEFAULT_SUPABASE_PUBLISHABLE_KEY = 'sb_publishable_8BlWpHJsYzB2V8GQh9kqdQ_QUjg7rN-'\n\nexport interface SupabaseLocalConfiguration { project: string; publishableKey: string }\nexport interface SupabaseConfiguration { url: string; publishableKey: string; source: 'local' | 'environment' | 'default' }\n\nfunction projectInputToUrl(project: string) {\n  const value = project.trim()\n  if (!value) throw new Error('Enter a Supabase project URL or project reference.')\n  if (/^https?:\\/\\//i.test(value)) return new URL(value).origin.replace(/\\/$/, '')\n  if (!/^[a-z0-9-]+$/i.test(value)) throw new Error('Invalid Supabase project reference.')\n  return `https://${value}.supabase.co`\n}\n\nexport function getSupabaseLocalOverride(): SupabaseLocalConfiguration | null {\n  if (typeof window === 'undefined') return null\n  try {\n    const raw=window.localStorage.getItem(SUPABASE_CONFIG_STORAGE_KEY); if(!raw) return null\n    const parsed=JSON.parse(raw) as Partial<SupabaseLocalConfiguration>\n    if(typeof parsed.project!=='string'||typeof parsed.publishableKey!=='string'||!parsed.project.trim()||!parsed.publishableKey.trim()) return null\n    return {project:parsed.project.trim(),publishableKey:parsed.publishableKey.trim()}\n  } catch { return null }\n}\n\nexport function getSupabaseConfiguration(): SupabaseConfiguration {\n  const local=getSupabaseLocalOverride()\n  if(local) return {url:projectInputToUrl(local.project),publishableKey:local.publishableKey,source:'local'}\n  const url=import.meta.env.VITE_SUPABASE_URL?.trim(), key=import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY?.trim()\n  if(url&&key) return {url:projectInputToUrl(url),publishableKey:key,source:'environment'}\n  return {url:DEFAULT_SUPABASE_URL,publishableKey:DEFAULT_SUPABASE_PUBLISHABLE_KEY,source:'default'}\n}\n\nexport function saveSupabaseLocalOverride(project:string,publishableKey:string){\n  if(typeof window==='undefined') return\n  const normalizedProject=project.trim(), normalizedKey=publishableKey.trim(); projectInputToUrl(normalizedProject)\n  if(!normalizedKey) throw new Error('Enter the Supabase publishable key.')\n  if(!normalizedKey.startsWith('sb_publishable_')&&!normalizedKey.startsWith('eyJ')) throw new Error('This does not look like a Supabase publishable/anon key.')\n  window.localStorage.setItem(SUPABASE_CONFIG_STORAGE_KEY,JSON.stringify({project:normalizedProject,publishableKey:normalizedKey}))\n}\nexport function clearSupabaseLocalOverride(){ if(typeof window!=='undefined') window.localStorage.removeItem(SUPABASE_CONFIG_STORAGE_KEY) }\n\nconst activeSupabaseConfiguration=getSupabaseConfiguration()\nexport const supabase = createClient(activeSupabaseConfiguration.url, activeSupabaseConfiguration.publishableKey, {"""
if old not in s: raise SystemExit('supabase anchor not found')
p.write_text(s.replace(old,new))

p = Path('src/components/InstructorAccountControls.tsx')
s = p.read_text()
insert = """import {\n  clearSupabaseLocalOverride,\n  getSupabaseConfiguration,\n  getSupabaseLocalOverride,\n  saveSupabaseLocalOverride,\n} from '../session/supabase'\n"""
s = s.replace("import '../account.css'\n", insert + "import '../account.css'\n")
state_anchor = "  const [editDescription, setEditDescription] = useState('')\n"
state_insert = """  const initialSupabaseConfig = getSupabaseLocalOverride()\n  const activeSupabaseConfig = getSupabaseConfiguration()\n  const [supabaseProject, setSupabaseProject] = useState(initialSupabaseConfig?.project ?? activeSupabaseConfig.url)\n  const [supabasePublishableKey, setSupabasePublishableKey] = useState(initialSupabaseConfig?.publishableKey ?? activeSupabaseConfig.publishableKey)\n  const [supabaseConfigMessage, setSupabaseConfigMessage] = useState<string | null>(null)\n  const [supabaseConfigError, setSupabaseConfigError] = useState<string | null>(null)\n"""
if state_anchor not in s: raise SystemExit('state anchor not found')
s=s.replace(state_anchor,state_anchor+state_insert)
handlers = """  useEffect(() => {\n    if (!settingsOpen) return\n    const local = getSupabaseLocalOverride()\n    const active = getSupabaseConfiguration()\n    setSupabaseProject(local?.project ?? active.url)\n    setSupabasePublishableKey(local?.publishableKey ?? active.publishableKey)\n    setSupabaseConfigMessage(null)\n    setSupabaseConfigError(null)\n  }, [settingsOpen])\n\n  const saveCentreSupabase = () => {\n    if (role !== 'standalone') { setSupabaseConfigError('End or leave the teaching session before changing centre configuration.'); return }\n    setSupabaseConfigMessage(null); setSupabaseConfigError(null)\n    try {\n      saveSupabaseLocalOverride(supabaseProject, supabasePublishableKey)\n      setSupabaseConfigMessage('Centre configuration saved. EDUVENT is reconnecting…')\n      window.setTimeout(() => window.location.reload(), 250)\n    } catch (cause) { setSupabaseConfigError(cause instanceof Error ? cause.message : 'Unable to save Supabase configuration.') }\n  }\n\n  const resetCentreSupabase = () => {\n    if (role !== 'standalone') { setSupabaseConfigError('End or leave the teaching session before changing centre configuration.'); return }\n    clearSupabaseLocalOverride()\n    setSupabaseConfigMessage('Local override cleared. EDUVENT is reconnecting to the deployment default…')\n    setSupabaseConfigError(null)\n    window.setTimeout(() => window.location.reload(), 250)\n  }\n\n"""
s=s.replace("  const staticPresets = useMemo(\n",handlers+"  const staticPresets = useMemo(\n")
settings_anchor = """            <div className=\"settings-summary-grid\">\n              <div><span>Version</span><strong>v0.65</strong></div>\n              <div><span>Teaching room</span><strong>2-hour lifetime</strong></div>\n              <div><span>Cloud</span><strong>{account ? 'Connected' : 'Not signed in'}</strong></div>\n            </div>\n\n"""
section = """            <div className=\"settings-summary-grid\">\n              <div><span>Version</span><strong>v0.66</strong></div>\n              <div><span>Teaching room</span><strong>2-hour lifetime</strong></div>\n              <div><span>Cloud</span><strong>{account ? 'Connected' : 'Not signed in'}</strong></div>\n            </div>\n\n            <section className=\"supabase-settings-section\">\n              <div className=\"scenario-settings-heading\">\n                <div><span>Centre configuration</span><h3>Supabase</h3></div>\n                <small>{getSupabaseConfiguration().source === 'local' ? 'Local override' : getSupabaseConfiguration().source === 'environment' ? 'Deployment environment' : 'Built-in default'}</small>\n              </div>\n              <p>Each centre can connect this EDUVENT installation to its own Supabase project. The configuration is stored only in this browser and overrides deployment environment variables.</p>\n              <div className=\"supabase-settings-fields\">\n                <label><span>Project URL or project reference</span><input value={supabaseProject} disabled={role !== 'standalone'} onChange={(event) => setSupabaseProject(event.target.value)} placeholder=\"e.g. abcdefghijklmnop or https://abcdefgh.supabase.co\" autoCapitalize=\"none\" autoCorrect=\"off\" spellCheck={false} /></label>\n                <label><span>Publishable key</span><input value={supabasePublishableKey} disabled={role !== 'standalone'} onChange={(event) => setSupabasePublishableKey(event.target.value)} placeholder=\"sb_publishable_…\" autoCapitalize=\"none\" autoCorrect=\"off\" spellCheck={false} /></label>\n              </div>\n              <div className=\"supabase-settings-actions\">\n                <button type=\"button\" className=\"account-primary-button\" disabled={role !== 'standalone'} onClick={saveCentreSupabase}>Save & reconnect</button>\n                <button type=\"button\" className=\"account-secondary-button\" disabled={role !== 'standalone' || !getSupabaseLocalOverride()} onClick={resetCentreSupabase}>Use deployment default</button>\n              </div>\n              <small className=\"supabase-settings-note\">The publishable key is browser-visible by design. Never enter a Supabase service-role or secret key here. Database and media security must be enforced with RLS.</small>\n              {role !== 'standalone' && <div className=\"account-hint\">Centre configuration is locked while a teaching session is active.</div>}\n              {supabaseConfigMessage && <div className=\"account-message\">{supabaseConfigMessage}</div>}\n              {supabaseConfigError && <div className=\"account-error\">{supabaseConfigError}</div>}\n            </section>\n\n"""
if settings_anchor not in s: raise SystemExit('settings anchor not found')
s=s.replace(settings_anchor,section).replace('v0.65','v0.66')
p.write_text(s)

p=Path('src/account.css');s=p.read_text();anchor='.scenario-settings-section { border-top: 1px solid #293941; padding-top: 17px; }\n'
css=""".supabase-settings-section { border-top: 1px solid #293941; padding: 17px 0; margin-bottom: 17px; border-bottom: 1px solid #293941; }\n.supabase-settings-section > p { margin: 9px 0 14px; color: #84979f; font-size: 11px; line-height: 1.45; }\n.supabase-settings-fields { display: grid; gap: 10px; }\n.supabase-settings-fields label { display: grid; gap: 6px; }\n.supabase-settings-fields label > span { color: #98aab2; font-size: 11px; }\n.supabase-settings-fields input { width: 100%; min-height: 42px; border: 1px solid #3a4d58; border-radius: 8px; background: #091116; color: #edf5f7; padding: 9px 11px; outline: none; font: inherit; }\n.supabase-settings-fields input:focus { border-color: #69c5e4; box-shadow: 0 0 0 2px rgba(105,197,228,.12); }\n.supabase-settings-fields input:disabled { opacity: .55; cursor: not-allowed; }\n.supabase-settings-actions { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 12px; }\n.supabase-settings-note { display: block; margin-top: 10px; color: #72858e; font-size: 9px; line-height: 1.45; }\n.supabase-settings-section .account-message, .supabase-settings-section .account-error { margin-top: 10px; }\n\n"""
if anchor not in s: raise SystemExit('css anchor not found')
p.write_text(s.replace(anchor,css+anchor))

